veil/integrations/_common.py:
"""Shared helpers for the Anthropic and OpenAI wrappers: masking/restoring
values inside arbitrary JSON-shaped message and tool-argument structures,
regardless of whether the SDK hands us a plain ``dict`` or a pydantic-style
model object.
"""

from __future__ import annotations

from typing import Any

from veil.masker import Masker


def mask_value(value: Any, masker: Masker) -> Any:
    """Recursively mask every string found in a JSON-shaped value."""
    if isinstance(value, str):
        return masker.mask(value)
    if isinstance(value, list):
        return [mask_value(v, masker) for v in value]
    if isinstance(value, dict):
        return {k: mask_value(v, masker) for k, v in value.items()}
    return value


def restore_value(value: Any, masker: Masker, *, tolerant: bool = True) -> Any:
    """Recursively restore every string found in a JSON-shaped value."""
    if isinstance(value, str):
        return masker.restore(value, tolerant=tolerant)
    if isinstance(value, list):
        return [restore_value(v, masker, tolerant=tolerant) for v in value]
    if isinstance(value, dict):
        return {k: restore_value(v, masker, tolerant=tolerant) for k, v in value.items()}
    return value


def model_copy_with(obj: Any, **updates: Any) -> Any:
    """Return a copy of ``obj`` with ``updates`` applied, whatever shape it is:
    a pydantic-style model (has ``model_copy``), a plain ``dict``, or a
    generic attribute-bearing object (e.g. ``types.SimpleNamespace``, as used
    by the fakes in this project's own tests, and often by other SDKs' test
    doubles too).
    """
    if hasattr(obj, "model_copy"):
        return obj.model_copy(update=updates)
    if isinstance(obj, dict):
        return {**obj, **updates}
    for key, val in updates.items():
        setattr(obj, key, val)
    return obj


def get_field(obj: Any, key: str, default: Any = None) -> Any:
    if isinstance(obj, dict):
        return obj.get(key, default)
    return getattr(obj, key, default)

veil/integrations/anthropic.py:
"""A thin wrapper around the Anthropic Python SDK that masks outgoing
messages and restores PII in the response, streaming included.

Requires the ``anthropic`` extra (``pip install "veil-pii[anthropic]"``).
This module only touches the SDK's public, documented surface
(``client.messages.create`` / ``client.messages.stream``, the
``MessageStream`` helper's ``text_stream`` / ``get_final_message()``) so it
works against the real SDK or against a test double shaped like it — see
``tests/test_integration_anthropic.py``, which uses fakes throughout since
this repo has no API key and makes no live calls.

**What gets masked:** every text block and tool-result content string in
``messages``, and every text block in ``system`` (both the plain-string and
the list-of-blocks forms). Images and other binary content pass through
untouched — veil only understands text.

**What gets restored:** every text block and tool_use ``input`` value in
the response, including from a token stream (via
:class:`veil.restore.Restorer`, so a surrogate split across chunks is still
caught).
"""

from __future__ import annotations

from collections.abc import Generator, Iterator
from dataclasses import dataclass, field
from typing import Any

from veil.integrations._common import get_field, model_copy_with, restore_value
from veil.masker import Masker
from veil.restore import Restorer


def mask_content(content: Any, masker: Masker) -> Any:
    """Mask a message's ``content`` field (a string, or a list of blocks)."""
    if isinstance(content, str):
        return masker.mask(content)
    if isinstance(content, list):
        return [_mask_block(b, masker) for b in content]
    return content


def _mask_block(block: Any, masker: Masker) -> Any:
    block_type = get_field(block, "type")
    if block_type == "text":
        text = get_field(block, "text")
        if isinstance(text, str):
            return model_copy_with(block, text=masker.mask(text))
    elif block_type == "tool_result":
        result_content = get_field(block, "content")
        if result_content is not None:
            return model_copy_with(block, content=mask_content(result_content, masker))
    return block


def mask_messages(messages: list[Any], masker: Masker) -> list[Any]:
    return [
        model_copy_with(m, content=mask_content(get_field(m, "content"), masker)) for m in messages
    ]


def mask_system(system: Any, masker: Masker) -> Any:
    if isinstance(system, str):
        return masker.mask(system)
    if isinstance(system, list):
        return [_mask_block(b, masker) for b in system]
    return system


def _restore_block(block: Any, masker: Masker) -> Any:
    block_type = get_field(block, "type")
    if block_type == "text":
        text = get_field(block, "text")
        if isinstance(text, str):
            return model_copy_with(block, text=masker.restore(text))
    elif block_type == "tool_use":
        tool_input = get_field(block, "input")
        if tool_input is not None:
            return model_copy_with(block, input=restore_value(tool_input, masker))
    return block


def restore_message(message: Any, masker: Masker) -> Any:
    """Restore a full (non-streamed) response message's content blocks."""
    content = get_field(message, "content")
    if not isinstance(content, list):
        return message
    return model_copy_with(message, content=[_restore_block(b, masker) for b in content])


@dataclass
class VeilMessageStream:
    """Wraps the Anthropic SDK's ``MessageStream`` (the object returned by
    ``client.messages.stream(...)``) so text arrives already restored.
    """

    raw: Any  # the object returned by client.messages.stream(...) (a context manager)
    masker: Masker
    _restorer: Restorer = field(init=False)
    _entered: Any = field(default=None, init=False)

    def __post_init__(self) -> None:
        self._restorer = Restorer(self.masker.vault)

    def __enter__(self) -> VeilMessageStream:
        self._entered = self.raw.__enter__()
        return self

    def __exit__(self, *exc_info: object) -> Any:
        return self.raw.__exit__(*exc_info)

    @property
    def text_stream(self) -> Generator[str, None, None]:
        stream = self._entered if self._entered is not None else self.raw
        for text in stream.text_stream:
            restored = self._restorer.feed(text)
            if restored:
                yield restored
        tail = self._restorer.flush()
        if tail:
            yield tail

    def __iter__(self) -> Iterator[Any]:
        """Yield raw SDK events, with text deltas restored in place.

        Tool-input JSON deltas (``input_json_delta`` / ``partial_json``) are
        passed through unrestored: they're accumulated fragments of a JSON
        string, not natural-language text, and are fully restored once
        assembled in :meth:`get_final_message`.
        """
        stream = self._entered if self._entered is not None else self.raw
        for event in stream:
            if get_field(event, "type") == "content_block_delta":
                delta = get_field(event, "delta")
                if get_field(delta, "type") == "text_delta":
                    text = get_field(delta, "text", "")
                    restored = self._restorer.feed(text)
                    event = model_copy_with(event, delta=model_copy_with(delta, text=restored))
            yield event

    def get_final_message(self) -> Any:
        stream = self._entered if self._entered is not None else self.raw
        message = stream.get_final_message()
        return restore_message(message, self.masker)


@dataclass
class AnthropicVeil:
    """Mask-and-restore wrapper around an ``anthropic.Anthropic`` client.

    Example::

        from anthropic import Anthropic
        from veil.integrations.anthropic import AnthropicVeil

        veil_client = AnthropicVeil(Anthropic())
        response = veil_client.create(
            model="claude-opus-5",
            max_tokens=1024,
            messages=[{"role": "user", "content": "Email alice@example.com"}],
        )
        # response.content[0].text has the real address restored, but the
        # model itself only ever saw a surrogate.
    """

    client: Any
    masker: Masker = field(default_factory=Masker)

    def create(self, *, messages: list[Any], system: Any = None, **kwargs: Any) -> Any:
        call_kwargs: dict[str, Any] = dict(kwargs)
        call_kwargs["messages"] = mask_messages(messages, self.masker)
        if system is not None:
            call_kwargs["system"] = mask_system(system, self.masker)
        response = self.client.messages.create(**call_kwargs)
        return restore_message(response, self.masker)

    def stream(
        self, *, messages: list[Any], system: Any = None, **kwargs: Any
    ) -> VeilMessageStream:
        call_kwargs: dict[str, Any] = dict(kwargs)
        call_kwargs["messages"] = mask_messages(messages, self.masker)
        if system is not None:
            call_kwargs["system"] = mask_system(system, self.masker)
        raw_stream = self.client.messages.stream(**call_kwargs)
        return VeilMessageStream(raw_stream, self.masker)

veil/integrations/openai.py:
"""A thin wrapper around the OpenAI Python SDK that masks outgoing messages
and restores PII in the response, streaming included.

Requires the ``openai`` extra (``pip install "veil-pii[openai]"``). Built
against the documented shape of ``client.chat.completions.create(...,
stream=True)`` — a message list of role/content dicts, and a stream of
``ChatCompletionChunk``-shaped objects with ``choices[].delta.content`` and
``choices[].delta.tool_calls[].function.arguments`` (a fragment of a JSON
*string*, unlike Anthropic's already-structured ``tool_use.input``). This
module makes no live API calls; see ``tests/test_integration_openai.py``
for the fakes it's tested against.

**Tool-call arguments are restored as raw text**, not parsed JSON: a
surrogate can straddle a `{`/`"`/`,` boundary mid-stream, so the argument
string is fed through :class:`veil.restore.Restorer` exactly like message
text, one :class:`~veil.restore.Restorer` per tool-call index (parallel
tool calls interleave their argument fragments by index, and each needs
its own held-back-prefix state).
"""

from __future__ import annotations

from collections.abc import Iterator
from dataclasses import dataclass, field
from typing import Any

from veil.integrations._common import get_field, model_copy_with
from veil.masker import Masker
from veil.restore import Restorer


def mask_content(content: Any, masker: Masker) -> Any:
    if isinstance(content, str):
        return masker.mask(content)
    if isinstance(content, list):
        return [_mask_content_block(b, masker) for b in content]
    return content


def _mask_content_block(block: Any, masker: Masker) -> Any:
    if get_field(block, "type") == "text":
        text = get_field(block, "text")
        if isinstance(text, str):
            return model_copy_with(block, text=masker.mask(text))
    return block


def _mask_tool_calls(tool_calls: Any, masker: Masker) -> Any:
    if not tool_calls:
        return tool_calls
    out = []
    for call in tool_calls:
        fn = get_field(call, "function")
        if fn is not None:
            args = get_field(fn, "arguments")
            if isinstance(args, str):
                fn = model_copy_with(fn, arguments=masker.mask(args))
            call = model_copy_with(call, function=fn)
        out.append(call)
    return out


def mask_messages(messages: list[Any], masker: Masker) -> list[Any]:
    """Mask ``content`` on every message (system/user/assistant/tool), and
    ``tool_calls[].function.arguments`` on any prior assistant turns being
    resent as history — those may contain real values a previous
    :meth:`veil.masker.Masker.restore` call put back; re-masking maps them
    to the *same* surrogate already in the vault rather than a new one.
    """
    out = []
    for message in messages:
        content = get_field(message, "content")
        updates: dict[str, Any] = {}
        if content is not None:
            updates["content"] = mask_content(content, masker)
        tool_calls = get_field(message, "tool_calls")
        if tool_calls:
            updates["tool_calls"] = _mask_tool_calls(tool_calls, masker)
        out.append(model_copy_with(message, **updates) if updates else message)
    return out


def restore_response(response: Any, masker: Masker) -> Any:
    """Restore a full (non-streamed) ``ChatCompletion`` response."""
    choices = get_field(response, "choices") or []
    return model_copy_with(response, choices=[_restore_choice(c, masker) for c in choices])


def _restore_choice(choice: Any, masker: Masker) -> Any:
    message = get_field(choice, "message")
    if message is None:
        return choice
    updates: dict[str, Any] = {}
    content = get_field(message, "content")
    if isinstance(content, str):
        updates["content"] = masker.restore(content)
    tool_calls = get_field(message, "tool_calls")
    if tool_calls:
        new_calls = []
        for call in tool_calls:
            fn = get_field(call, "function")
            if fn is not None:
                args = get_field(fn, "arguments")
                if isinstance(args, str):
                    fn = model_copy_with(fn, arguments=masker.restore(args))
                call = model_copy_with(call, function=fn)
            new_calls.append(call)
        updates["tool_calls"] = new_calls
    if not updates:
        return choice
    return model_copy_with(choice, message=model_copy_with(message, **updates))


@dataclass
class OpenAIVeilStream:
    """Wraps the raw chunk iterator from ``client.chat.completions.create(
    ..., stream=True)`` so text and tool-call arguments arrive restored.
    """

    raw: Iterator[Any]
    masker: Masker
    _content_restorer: Restorer = field(init=False)
    _tool_restorers: dict[int, Restorer] = field(init=False, default_factory=dict)

    def __post_init__(self) -> None:
        self._content_restorer = Restorer(self.masker.vault)

    def __iter__(self) -> Iterator[Any]:
        for chunk in self.raw:
            yield self._restore_chunk(chunk)
        yield from self._flush_trailing()

    def _restore_chunk(self, chunk: Any) -> Any:
        choices = get_field(chunk, "choices") or []
        new_choices = [self._restore_choice_delta(c) for c in choices]
        return model_copy_with(chunk, choices=new_choices) if choices else chunk

    def _restore_choice_delta(self, choice: Any) -> Any:
        delta = get_field(choice, "delta")
        if delta is None:
            return choice
        updates: dict[str, Any] = {}
        content = get_field(delta, "content")
        if isinstance(content, str):
            updates["content"] = self._content_restorer.feed(content)
        tool_calls = get_field(delta, "tool_calls")
        if tool_calls:
            updates["tool_calls"] = [self._restore_tool_call_delta(c) for c in tool_calls]
        if not updates:
            return choice
        return model_copy_with(choice, delta=model_copy_with(delta, **updates))

    def _restore_tool_call_delta(self, call: Any) -> Any:
        fn = get_field(call, "function")
        if fn is None:
            return call
        args = get_field(fn, "arguments")
        if not isinstance(args, str):
            return call
        index = get_field(call, "index", 0)
        restorer = self._tool_restorers.setdefault(index, Restorer(self.masker.vault))
        return model_copy_with(call, function=model_copy_with(fn, arguments=restorer.feed(args)))

    def _flush_trailing(self) -> Iterator[Any]:
        """After the real stream ends, emit any text still held back
        because it could have been (but wasn't) the start of a surrogate.
        Synthesized as plain dict chunks, since we can't construct a real
        SDK response object without its private constructor.
        """
        tail = self._content_restorer.flush()
        if tail:
            yield {"choices": [{"index": 0, "delta": {"content": tail}}]}
        for index, restorer in self._tool_restorers.items():
            tail = restorer.flush()
            if tail:
                yield {
                    "choices": [
                        {
                            "index": 0,
                            "delta": {
                                "tool_calls": [{"index": index, "function": {"arguments": tail}}]
                            },
                        }
                    ]
                }


@dataclass
class OpenAIVeil:
    """Mask-and-restore wrapper around an ``openai.OpenAI`` client.

    Example::

        from openai import OpenAI
        from veil.integrations.openai import OpenAIVeil

        veil_client = OpenAIVeil(OpenAI())
        response = veil_client.create(
            model="gpt-4o",
            messages=[{"role": "user", "content": "Email alice@example.com"}],
        )
    """

    client: Any
    masker: Masker = field(default_factory=Masker)

    def create(self, *, messages: list[Any], **kwargs: Any) -> Any:
        masked = mask_messages(messages, self.masker)
        response = self.client.chat.completions.create(messages=masked, **kwargs)
        return restore_response(response, self.masker)

    def stream(self, *, messages: list[Any], **kwargs: Any) -> OpenAIVeilStream:
        masked = mask_messages(messages, self.masker)
        raw = self.client.chat.completions.create(messages=masked, stream=True, **kwargs)
        return OpenAIVeilStream(raw, self.masker)

veil/vault.py:
"""The vault: the original-value <-> surrogate mapping for one session.

**Threat model, stated honestly.** The vault is what makes masking
*reversible*, which means it is also the single artifact that can undo
veil's protection: anyone who reads it can de-anonymize the masked text.
veil treats it accordingly:

- In memory by default. Nothing touches disk unless you call
  :meth:`Vault.to_json` / :meth:`Vault.save` yourself.
- JSON serialization is plaintext by design (so you can inspect, diff, or
  hand-audit it) — **do not** commit it, log it, or send it anywhere the
  masked prompt itself isn't already allowed to go.
- The optional Fernet encryption (``pip install "veil-pii[vault-crypto]"``)
  protects a vault *at rest* (on disk, in object storage) against someone
  who obtains the file but not the key. It does **not** protect against a
  compromised process that holds both the vault and the key in memory, and
  it does not provide forward secrecy, key rotation, or audit logging —
  those are your application's job. Store the key separately from the
  vault (a secrets manager, not the same disk directory).
- veil never phones home and never transmits the vault anywhere.

Restoration only works while the vault used to mask a given conversation is
kept alive (in memory, or reloaded from its saved JSON) for that
conversation's duration.
"""

from __future__ import annotations

import json
from dataclasses import dataclass, field
from typing import Any

from veil.surrogates import SurrogateGenerator
from veil.types import EntityType, Mapping


class VaultError(Exception):
    """Raised for vault serialization/deserialization/crypto failures."""


@dataclass
class Vault:
    """Bidirectional original<->surrogate map, consistent within a session."""

    _by_original: dict[tuple[EntityType, str], Mapping] = field(default_factory=dict)
    _by_surrogate: dict[str, Mapping] = field(default_factory=dict)
    _counters: dict[EntityType, int] = field(default_factory=dict)

    def get_or_create(
        self,
        entity_type: EntityType,
        original: str,
        generator: SurrogateGenerator,
        detector: str = "",
    ) -> str:
        """Return the existing surrogate for ``original``, minting one if new."""
        key = (entity_type, original)
        existing = self._by_original.get(key)
        if existing is not None:
            return existing.surrogate

        index = self._counters.get(entity_type, 0) + 1
        self._counters[entity_type] = index
        surrogate = generator.generate(entity_type, original, index)
        # Extremely unlikely, but guard against a generator producing a
        # surrogate that collides with an existing one for another value.
        while surrogate in self._by_surrogate:
            index += 1
            self._counters[entity_type] = index
            surrogate = generator.generate(entity_type, original, index)

        mapping = Mapping(
            type=entity_type, original=original, surrogate=surrogate, first_seen=detector
        )
        self._by_original[key] = mapping
        self._by_surrogate[surrogate] = mapping
        return surrogate

    def lookup_surrogate(self, surrogate: str) -> Mapping | None:
        return self._by_surrogate.get(surrogate)

    def lookup_original(self, entity_type: EntityType, original: str) -> Mapping | None:
        return self._by_original.get((entity_type, original))

    def surrogates(self) -> list[str]:
        """All surrogate strings, longest first (useful for restore matching)."""
        return sorted(self._by_surrogate.keys(), key=len, reverse=True)

    def originals(self) -> list[str]:
        """All original values that should never leak into outgoing text."""
        return [m.original for m in self._by_original.values()]

    def mappings(self) -> list[Mapping]:
        return list(self._by_original.values())

    def __len__(self) -> int:
        return len(self._by_original)

    def to_dict(self) -> dict[str, Any]:
        return {
            "version": 1,
            "mappings": [
                {
                    "type": m.type.value,
                    "original": m.original,
                    "surrogate": m.surrogate,
                    "detector": m.first_seen,
                }
                for m in self._by_original.values()
            ],
        }

    def to_json(self, *, indent: int | None = 2) -> str:
        return json.dumps(self.to_dict(), indent=indent, ensure_ascii=False)

    @classmethod
    def from_dict(cls, data: dict[str, Any]) -> Vault:
        vault = cls()
        for entry in data.get("mappings", []):
            try:
                etype = EntityType(entry["type"])
            except ValueError as exc:
                raise VaultError(f"unknown entity type in vault data: {entry['type']!r}") from exc
            mapping = Mapping(
                type=etype,
                original=entry["original"],
                surrogate=entry["surrogate"],
                first_seen=entry.get("detector", ""),
            )
            vault._by_original[(etype, mapping.original)] = mapping
            vault._by_surrogate[mapping.surrogate] = mapping
            vault._counters[etype] = vault._counters.get(etype, 0) + 1
        return vault

    @classmethod
    def from_json(cls, data: str) -> Vault:
        try:
            parsed = json.loads(data)
        except json.JSONDecodeError as exc:
            raise VaultError(f"invalid vault JSON: {exc}") from exc
        return cls.from_dict(parsed)

    def save(self, path: str) -> None:
        with open(path, "w", encoding="utf-8") as f:
            f.write(self.to_json())

    @classmethod
    def load(cls, path: str) -> Vault:
        with open(path, encoding="utf-8") as f:
            return cls.from_json(f.read())

    # -- Optional at-rest encryption (requires the 'vault-crypto' extra) --

    def encrypt(self, key: bytes) -> bytes:
        """Encrypt the vault's JSON with Fernet (AES-128-CBC + HMAC). See
        the module docstring for what this does and doesn't protect against.
        """
        try:
            from cryptography.fernet import Fernet  # noqa: PLC0415
        except ImportError as exc:
            raise VaultError(
                "encrypt() requires the 'vault-crypto' extra: "
                'pip install "veil-pii[vault-crypto]"'
            ) from exc
        return Fernet(key).encrypt(self.to_json(indent=None).encode("utf-8"))

    @classmethod
    def decrypt(cls, token: bytes, key: bytes) -> Vault:
        try:
            from cryptography.fernet import Fernet, InvalidToken  # noqa: PLC0415
        except ImportError as exc:
            raise VaultError(
                "decrypt() requires the 'vault-crypto' extra: "
                'pip install "veil-pii[vault-crypto]"'
            ) from exc
        try:
            plaintext = Fernet(key).decrypt(token)
        except InvalidToken as exc:
            raise VaultError("wrong key, or vault data is corrupted/tampered") from exc
        return cls.from_json(plaintext.decode("utf-8"))

    @staticmethod
    def generate_key() -> bytes:
        try:
            from cryptography.fernet import Fernet  # noqa: PLC0415
        except ImportError as exc:
            raise VaultError(
                "generate_key() requires the 'vault-crypto' extra: "
                'pip install "veil-pii[vault-crypto]"'
            ) from exc
        return Fernet.generate_key()
